function Badge({children,tone=''}){return <span className={'badge '+tone}>{children}</span>;}
const values=v=>Array.isArray(v)?v:v&&typeof v==='object'?Object.values(v):[];
const mergeRequests=data=>values(data.mergeRequestViews??data.mergeRequests??data.mr?.mergeRequests).map(m=>m.merge_request?{...m.merge_request,...m}:m);
