 useEffect(()=>{if(!('modelContext' in navigator))return;const tool={name:'inspect_decision_workspace',description:'Read immutable proposal revisions, evidence and pending decisions in the current Git workspace.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify(await api('/workspace'))}]})};try{navigator.modelContext.registerTool(tool);}catch{}return ()=>{try{navigator.modelContext.unregisterTool(tool.name);}catch{}};},[]);
 async function demo(action){setDemoMenu(false);setBusy(true);try{setData(await api('/demo/'+action,{method:'POST'}));setSelected(null);setMrId(null);message(action==='reset'?'Fresh workspace created. Answer the context question before producers start.':'Decision basis changed. Open a decision to review fresh evidence.');}catch(e){message(e.message,'error');}finally{setBusy(false);}}
 const openDecision=id=>{setMrId(null);setProposal(null);setSelected(id);setTab('decisions');};
 if(authRequired&&!data)return <div className="loading"><GitFork size={32}/><h2>Connect to your workspace</h2><p>Use your owner credential to inspect and resolve decisions.</p><form className="auth-form" onSubmit={async e=>{e.preventDefault();ownerCredential=credential;try{await reload();setAuthRequired(false);setCredential('');}catch(err){ownerCredential='';message(err.message,'error');}}}><input type="password" aria-label="Owner credential" autoComplete="off" value={credential} onChange={e=>setCredential(e.target.value)} placeholder="Owner credential" required/><button className="button dark">Connect</button></form><p>The credential stays in this page’s memory.</p>{toast&&<p role="alert">{toast.text}</p>}</div>;
 if(!data)return <div className="loading"><GitFork size={32}/><h2>Opening your workspace</h2><p>Reading Git state and immutable evidence…</p>{toast&&<p>{toast.text}</p>}</div>;
