        {(data.discovery?.conventional_review_ids??[]).length>0&&<div className="review-notice"><h3>Conventional review</h3><p>Review these Git changes individually or prepare a checked composition.</p>{data.discovery.conventional_review_ids.map(id=><button className="button outline small" key={id} onClick={()=>setProposal(id)}>{data.proposals.find(p=>p.id===data.revisions.find(r=>r.id===id)?.proposal_id)?.title}</button>)}</div>}
        {data.proposals.length>0&&<details className="work-details"><summary>Why these decisions?</summary><p>{data.discovery?.explanation}</p><p>{summary.independentWork} independent proposal histories remain outside the blocking graph. The displayed compositions explicitly include eligible independent work. {summary.contextAnswersRecorded} context answer(s) recorded before work are counted separately from these review decisions. Tests establish only their listed scenarios.</p></details>}
